## Overview
Create the SQLite database client using better-sqlite3 with platform-specific database path resolution.

## Context
The database is shared between web app and CLI. It must be created in the correct location based on the operating system.

## File to Create

### /packages/shared/src/db/client.ts
```typescript
import Database from 'better-sqlite3';
import path from 'path';
import os from 'os';
import fs from 'fs';

/**
 * Get the platform-specific database directory
 */
export function getDbPath(): string {
  const platform = os.platform();
  let baseDir: string;

  switch (platform) {
    case 'darwin':
      baseDir = path.join(os.homedir(), 'Library', 'Application Support', 'contextkit');
      break;
    case 'win32':
      baseDir = path.join(process.env.APPDATA || os.homedir(), 'contextkit');
      break;
    default: // linux and others
      baseDir = path.join(os.homedir(), '.local', 'share', 'contextkit');
  }

  // Ensure directory exists
  fs.mkdirSync(baseDir, { recursive: true });

  return path.join(baseDir, 'contextkit.db');
}

let db: Database.Database | null = null;

/**
 * Get or create the database connection
 */
export function getDb(): Database.Database {
  if (\!db) {
    const dbPath = getDbPath();
    db = new Database(dbPath);
    db.pragma('journal_mode = WAL');
  }
  return db;
}

/**
 * Close the database connection
 */
export function closeDb(): void {
  if (db) {
    db.close();
    db = null;
  }
}

/**
 * For testing: create in-memory database
 */
export function getTestDb(): Database.Database {
  return new Database(':memory:');
}
```

## Database Locations
- macOS: ~/Library/Application Support/contextkit/contextkit.db
- Linux: ~/.local/share/contextkit/contextkit.db
- Windows: %APPDATA%/contextkit/contextkit.db

## Acceptance Criteria
- [ ] Database created in correct platform-specific path
- [ ] Directory created if it doesn't exist
- [ ] WAL mode enabled for better performance
- [ ] Connection reused (singleton pattern)
- [ ] Test helper for in-memory database

