## Overview
Implement local text embedding generation using @xenova/transformers with the all-MiniLM-L6-v2 model.

## Context
We generate embeddings entirely locally for privacy. The model is automatically downloaded and cached at ~/.cache/huggingface/ on first use.

## File to Create

### /packages/shared/src/embeddings.ts
```typescript
import { pipeline, Pipeline } from '@xenova/transformers';

let embedder: Pipeline | null = null;

/**
 * Get or initialize the embedding pipeline
 * Model is cached at ~/.cache/huggingface/
 */
async function getEmbedder(): Promise<Pipeline> {
  if (\!embedder) {
    embedder = await pipeline(
      'feature-extraction',
      'Xenova/all-MiniLM-L6-v2'
    );
  }
  return embedder;
}

/**
 * Generate embedding for text
 * Returns 384-dimensional vector
 */
export async function getEmbedding(text: string): Promise<number[]> {
  const pipe = await getEmbedder();

  const output = await pipe(text, {
    pooling: 'mean',
    normalize: true
  });

  // Convert Float32Array to regular array
  return Array.from(output.data as Float32Array);
}

/**
 * Generate embedding for a snippet
 * Combines title, tags, and content for better semantic matching
 */
export async function getSnippetEmbedding(
  title: string,
  tags: string[],
  content: string
): Promise<number[]> {
  // Combine fields with separators for embedding
  const text = \`\${title}\n\${tags.join(', ')}\n\${content}\`;
  return getEmbedding(text);
}

/**
 * Check if model is downloaded
 */
export async function isModelReady(): Promise<boolean> {
  try {
    await getEmbedder();
    return true;
  } catch {
    return false;
  }
}

/**
 * Preload the model (useful for CLI doctor command)
 */
export async function preloadModel(): Promise<{ latencyMs: number }> {
  const start = Date.now();
  await getEmbedder();
  return { latencyMs: Date.now() - start };
}
```

## Model Details
- Model: Xenova/all-MiniLM-L6-v2
- Output: 384-dimensional vectors
- Cache: ~/.cache/huggingface/
- Size: ~90MB download

## Acceptance Criteria
- [ ] Model downloads on first use
- [ ] Subsequent calls use cached model
- [ ] Embeddings are 384-dimensional
- [ ] Embeddings are normalized (unit vectors)
- [ ] Works offline after initial download

