## Overview
Integrate the sqlite-vss extension to enable vector similarity search in SQLite.

## Context
sqlite-vss is a SQLite extension that adds vector search capabilities. We use it for semantic similarity search of snippets based on their embeddings.

## File to Create

### /packages/shared/src/db/vectors.ts
```typescript
import { Database } from 'better-sqlite3';

/**
 * Load the sqlite-vss extension
 * Note: sqlite-vss must be installed/available on the system
 */
export function loadVssExtension(db: Database): void {
  // Load vector0 and vss0 extensions
  db.loadExtension('vector0');
  db.loadExtension('vss0');
}

/**
 * Initialize the vector search virtual table
 * all-MiniLM-L6-v2 produces 384-dimensional vectors
 */
export function initVectorTable(db: Database): void {
  db.exec(\`
    CREATE VIRTUAL TABLE IF NOT EXISTS snippet_embeddings USING vss0(
      embedding(384)
    );
  \`);
}

/**
 * Insert or update an embedding for a snippet
 */
export function upsertEmbedding(
  db: Database,
  snippetId: string,
  embedding: number[]
): void {
  // Check if mapping exists
  const existing = db.prepare(
    'SELECT rowid FROM snippet_embedding_map WHERE snippet_id = ?'
  ).get(snippetId) as { rowid: number } | undefined;

  if (existing) {
    // Update existing embedding
    db.prepare(
      'UPDATE snippet_embeddings SET embedding = ? WHERE rowid = ?'
    ).run(JSON.stringify(embedding), existing.rowid);
  } else {
    // Insert new embedding
    const result = db.prepare(
      'INSERT INTO snippet_embeddings(embedding) VALUES (?)'
    ).run(JSON.stringify(embedding));

    // Map snippet to embedding rowid
    db.prepare(
      'INSERT INTO snippet_embedding_map(snippet_id, rowid) VALUES (?, ?)'
    ).run(snippetId, result.lastInsertRowid);
  }
}

/**
 * Search for similar snippets by embedding
 */
export function searchSimilar(
  db: Database,
  queryEmbedding: number[],
  limit: number = 10
): Array<{ snippetId: string; distance: number }> {
  const results = db.prepare(\`
    SELECT 
      m.snippet_id,
      e.distance
    FROM snippet_embeddings e
    JOIN snippet_embedding_map m ON m.rowid = e.rowid
    WHERE vss_search(e.embedding, ?)
    LIMIT ?
  \`).all(JSON.stringify(queryEmbedding), limit) as Array<{
    snippet_id: string;
    distance: number;
  }>;

  return results.map(r => ({
    snippetId: r.snippet_id,
    distance: r.distance
  }));
}

/**
 * Delete embedding for a snippet
 */
export function deleteEmbedding(db: Database, snippetId: string): void {
  const mapping = db.prepare(
    'SELECT rowid FROM snippet_embedding_map WHERE snippet_id = ?'
  ).get(snippetId) as { rowid: number } | undefined;

  if (mapping) {
    db.prepare('DELETE FROM snippet_embeddings WHERE rowid = ?').run(mapping.rowid);
    db.prepare('DELETE FROM snippet_embedding_map WHERE snippet_id = ?').run(snippetId);
  }
}
```

## Installation Note
sqlite-vss requires native compilation. May need to:
- Install via Homebrew on macOS: `brew install sqlite-vss`
- Use pre-built binaries for other platforms
- Or bundle the extension with the app

## Known Risk
Native extension compatibility across platforms needs validation.

## Acceptance Criteria
- [ ] vss extension loads successfully
- [ ] Virtual table created with 384 dimensions
- [ ] Can insert embeddings
- [ ] Can search for similar embeddings
- [ ] Can delete embeddings

