## Overview
Create high-level vector search utilities that combine embeddings and database operations for semantic snippet search.

## Context
This is the final piece of the shared library - it ties together embeddings and database to provide the search functionality used by the CLI.

## File to Create

### /packages/shared/src/search.ts
```typescript
import { Database } from 'better-sqlite3';
import { Snippet, SearchResult } from './types';
import { getEmbedding } from './embeddings';
import { searchSimilar } from './db/vectors';

/**
 * Search for snippets by semantic similarity
 */
export async function searchSnippets(
  db: Database,
  query: string,
  limit: number = 10
): Promise<SearchResult[]> {
  // Generate embedding for query
  const queryEmbedding = await getEmbedding(query);

  // Search for similar embeddings
  const matches = searchSimilar(db, queryEmbedding, limit);

  // Fetch full snippet data for matches
  const results: SearchResult[] = [];

  for (const match of matches) {
    const row = db.prepare(
      'SELECT * FROM snippets WHERE id = ?'
    ).get(match.snippetId) as any;

    if (row) {
      const snippet: Snippet = {
        id: row.id,
        title: row.title,
        content: row.content,
        tags: JSON.parse(row.tags),
        createdAt: row.created_at,
        updatedAt: row.updated_at
      };

      // Convert distance to similarity score (0-1)
      // Lower distance = higher similarity
      const score = 1 / (1 + match.distance);

      results.push({ snippet, score });
    }
  }

  // Sort by score descending
  return results.sort((a, b) => b.score - a.score);
}

/**
 * Update embedding when snippet changes
 */
export async function updateSnippetEmbedding(
  db: Database,
  snippet: Snippet
): Promise<void> {
  const { getSnippetEmbedding } = await import('./embeddings');
  const { upsertEmbedding } = await import('./db/vectors');

  const embedding = await getSnippetEmbedding(
    snippet.title,
    snippet.tags,
    snippet.content
  );

  upsertEmbedding(db, snippet.id, embedding);
}
```

