## Overview
Define the core TypeScript interfaces for ContextKit: Snippet, SnippetVersion, ProjectConfig, and SearchResult.

## Context
These types are the contract between all packages. They must be carefully designed as changes will ripple through the entire codebase.

## File to Create

### /packages/shared/src/types.ts
```typescript
/**
 * A context snippet stored in the database
 */
export interface Snippet {
  id: string;           // UUID
  title: string;
  content: string;      // Markdown content
  tags: string[];       // Array of tag strings
  createdAt: string;    // ISO timestamp
  updatedAt: string;    // ISO timestamp
}

/**
 * A historical version of a snippet
 */
export interface SnippetVersion {
  id: string;           // UUID
  snippetId: string;    // Foreign key to Snippet
  title: string;
  content: string;
  tags: string[];
  createdAt: string;    // When this version was created
}

/**
 * Project-level configuration stored in .contextkit/config.json
 */
export interface ProjectConfig {
  version: 1;
  selectedSnippets: SelectedSnippet[];
}

export interface SelectedSnippet {
  id: string;
  title: string;
  selectedAt: string;   // ISO timestamp
}

/**
 * Result from semantic search
 */
export interface SearchResult {
  snippet: Snippet;
  score: number;        // Similarity score (0-1)
}

/**
 * Input for creating a new snippet
 */
export interface CreateSnippetInput {
  title: string;
  content: string;
  tags: string[];
}

/**
 * Input for updating an existing snippet
 */
export interface UpdateSnippetInput {
  title?: string;
  content?: string;
  tags?: string[];
}
```

